import { db } from "../shared/db.js";
import { DomainError, Result } from "../shared/result.js";
import { Assinatura } from "./assinatura.js";
export class RenovarAssinaturaHandler {
  public async execute(id: string): Promise<Result<Assinatura, DomainError>> {
    const { data } = await db.from("assinaturas").select("*").eq("id", id).maybeSingle();
    if (!data) return { ok: false, error: new DomainError("subscription.not-found") };
    const a = Object.assign(new Assinatura(), data);
    a.fimPeriodo = new Date(a.fimPeriodo.getTime() + 30 * 86400000);
    await db.from("assinaturas").update({ fim_periodo: a.fimPeriodo }).eq("id", id);
    return { ok: true, value: a };
  }
}

