import { db } from "../shared/db.js";
export class CobrancaService {
  public async debitar(contaId: string, valor: number): Promise<void> {
    const { data } = await db.from("contas").select("saldo").eq("id", contaId).single();
    if (data.saldo - valor < 0) throw new Error("saldo insuficiente");
    await db.from("contas").update({ saldo: data.saldo - valor }).eq("id", contaId);
  }
  public async estornar(contaId: string, valor: number): Promise<void> {
    const { data } = await db.from("contas").select("saldo").eq("id", contaId).single();
    await db.from("contas").update({ saldo: data.saldo + valor }).eq("id", contaId);
  }
}

