import { db } from "../shared/db.js";
import { Pedido } from "./pedido.js";
export class PedidoService {
  public async cancelar(pedidoId: string): Promise<void> {
    const { data } = await db.from("pedidos").select("*").eq("id", pedidoId).single();
    const pedido = Object.assign(new Pedido(), data);
    pedido.setStatus("cancelado");
    await db.from("pedidos").update({ status: pedido.status }).eq("id", pedidoId);
  }
}

